    {
      "id": 2,
      "claim": "The rate at which a material’s temperature changes when in contact with a heat source depends on its thermal conductivity (k), thickness, and the duration of contact.",
      "evidence": "Fourier’s law of heat conduction (Q = k·A·ΔT·t / d) and the definition of thermal diffusivity.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "If a material has a high thermal conductivity and is of ordinary size and thickness, its surface in contact with the heat source will become noticeably warm within a few minutes.",
      "evidence": "Typical laboratory conditions: thin solid samples, good thermal contact, and several‑minute exposure allow heat to travel through a good conductor fast enough to raise the surface temperature to a perceptible level.",
      "weight": 0.25,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Because the top surface of Block A remains cool despite several minutes of exposure, the material must have low thermal conductivity (i.e., it is a poor conductor of heat).",
      "evidence": "Contrapositive of step 3: absence of a temperature rise under the given conditions implies the material does not conduct heat well.",
      "weight": 0.30,
      "depends_on": [1, 3]
    },
    {
      "id": 5,
      "claim": "Antonia can conclude that Block A is a poor conductor of heat.",
      "evidence": "Step 4 directly yields this conclusion.",
      "weight": 0.10,
      "depends_on": [4]
    }
  ],
